def or_not_true(prog):
    nots = {ops[0]: ops[1] for op, ops in prog if op == "NOT" and len(ops) == 2}
    return each(prog, lambda o, a: o == "OR" and len(a) == 3 and (nots.get(a[2]) == a[1] or nots.get(a[1]) == a[2]),
                lambda o, a: ["FILL", [a[0], "TRUE", a[1]]])


def check_nullable(prog, sch):
    """'col op lit' -> FILL TRUE when the column's check bounds make it true, NULLs ignored."""
    lm = load_map(prog)
    out = []
    for i, (op, ops) in enumerate(prog):
        tc = lm[i].get(ops[1]) if op in ("GT", "GE", "LT", "LE") and len(ops) == 3 else None
        if tc and is_num_lit(ops[2]):
            t, c = tc.split(".")
            chk = {k.lower(): v for k, v in sch.table(t).get("check", {}).items()}.get(c.lower())
            if chk:
                from decimal import Decimal
                lo, hi = (None if x is None else Decimal(str(x)) for x in chk)
                v = Decimal(ops[2])
                holds = {"GE": lo is not None and lo >= v, "GT": lo is not None and lo > v,
                         "LE": hi is not None and hi <= v, "LT": hi is not None and hi < v}[op]
                if holds:
                    out.append(["FILL", [ops[0], "TRUE", ops[1]]])
                    continue
        out.append([op, ops])
    return out


def selfjoin_keep_null(prog):
    """HJOIN a, b, k, k / GROUP g, a / AGG m, g, GATHER(s, b) / GATHER r, a, GFIRST(g)
    -> GROUP g2, k over every row (the NULL keys become a group), r = 0..n-1."""
    joins = [(ops[0], ops[1], ops[2]) for op, ops in prog
             if op in TWO_DEST and len(ops) == 4 and ops[0] != ops[1] and ops[2] == ops[3]]
    if not joins:
        return prog
    a, b, k = joins[0]
    groups = {ops[0] for op, ops in prog if op == "GROUP" and ops[1:] == [a]}
    firsts = {ops[0] for op, ops in prog if op == "GFIRST" and ops[1] in groups}
    viab = {ops[0]: ops[1] for op, ops in prog if op == "GATHER" and ops[2] == b}
    if not groups:
        return prog
    out = []
    for op, ops in prog:
        if op in TWO_DEST and ops[:2] == [a, b]:
            out += [["IOTA", ["_fksj", k]], ["GROUP", ["_fksg", k]], ["GID", ["_fksi", "_fksg"]]]
        elif op in ("GMAX", "GMIN", "GSUM", "GCOUNTV") and ops[1] in groups and ops[2] in viab:
            out += [[op, ["_fksm", "_fksg", viab[ops[2]]]], ["GATHER", [ops[0], "_fksm", "_fksi"]]]
        elif op == "GATHER" and ops[1] == a and ops[2] in firsts:
            out.append(["GATHER", [ops[0], "_fksj", "_fksj"]])
        else:
            out.append([op, ops])
    return dce(out)


def isnull_two_ops(prog):
    defs = {ops[0]: (op, ops) for op, ops in prog if op in ELEMENTWISE and len(ops) == 3}
    def pick(o, a):
        d = defs.get(a[1])
        return d is not None and all(is_reg(t) for t in d[1][1:]) and d[1][1] != d[1][2]
    return each(prog, lambda o, a: o == "ISNULL" and len(a) == 2 and pick(o, a),
                lambda o, a: ["ISNULL", [a[0], defs[a[1]][1][1]]])
